// === 予約日時計算（全文置換）===
// 入力はどちらでも可：
//  - $json.start_at / end_at / timezone
//  - $json.output.start_at / end_at / timezone

const j = $json;

const startRaw = j.start_at ?? j.output?.start_at ?? null;
const endRaw   = j.end_at   ?? j.output?.end_at   ?? null;
const tz       = j.timezone ?? j.output?.timezone ?? 'Asia/Tokyo';

if (!startRaw) {
  throw new Error('start_at is missing');
}

const start = new Date(startRaw);
if (isNaN(start.getTime())) {
  throw new Error(`start_at is invalid: ${startRaw}`);
}

const end = endRaw ? new Date(endRaw) : null;
if (endRaw && isNaN(end.getTime())) {
  throw new Error(`end_at is invalid: ${endRaw}`);
}

// ---- ここからリマインド時間計算（Asia/Tokyo 前提）----

// JSTオフセット（分）
const JST_OFFSET_MIN = 9 * 60;

// 開始日時を「JSTのカレンダー時間」として扱う
const startJstMs = start.getTime() + JST_OFFSET_MIN * 60 * 1000;
const startJst = new Date(startJstMs);

// 前日18:00 JST
const prev18Jst = new Date(startJst);
prev18Jst.setDate(prev18Jst.getDate() - 1);
prev18Jst.setHours(18, 0, 0, 0);

// 当日1時間前 JST
const oneHourBeforeJst = new Date(startJst);
oneHourBeforeJst.setHours(oneHourBeforeJst.getHours() - 1);

// Wait ノード用に UTC に戻す
const prev18Utc = new Date(prev18Jst.getTime() - JST_OFFSET_MIN * 60 * 1000);
const oneHourBeforeUtc = new Date(oneHourBeforeJst.getTime() - JST_OFFSET_MIN * 60 * 1000);

// ---- 補助フラグ ----
const now = new Date();
const ms = 60 * 1000;

const minutes_until_start =
  Math.round((start.getTime() - now.getTime()) / ms);

const within_24h =
  (start.getTime() - now.getTime()) > 0 &&
  (start.getTime() - now.getTime()) <= 24 * 60 * ms;

// ---- 返却 ----
return [{
  tz,
  start_at_src: startRaw,
  start_at_iso: start.toISOString(),
  end_at_iso: end ? end.toISOString() : null,

  // リマインド用（Wait ノードでそのまま使う）
  remind_prev18_iso: prev18Utc.toISOString(),      // 前日18:00 JST 相当
  morning_at_iso:    oneHourBeforeUtc.toISOString(), // 当日1時間前 JST 相当

  // チェック用
  minutes_until_start,
  within_24h,
  now_iso: now.toISOString(),
  is_before_prev18: now.getTime() < prev18Utc.getTime(),
  is_between_prev18_and_start:
    now.getTime() >= prev18Utc.getTime() && now.getTime() < start.getTime(),
}];

const userId   = $node["LINE Webhook"].json.body.events[0].source.userId;
const replyTxt = $node["Message a model"].json.message.content;

return [
  {
    json: {
      to: userId,
      messages: [
        {
          type: "text",
          text: replyTxt,
        },
      ],
    },
  },
];
